tina.', 'nome' => 'Ricardo Mendes', 'profissao' => 'Gestor empresarial', 'foto' => '/assets/images/depoimento-gestor.png']]; $storyExamples = true; endif; ?><?php if ($storyCards !== []): ?><div class="members-story-slider" data-story-slider><?php foreach ($storyCards as $i => $story): ?><article class="members-story-card" data-story-card <?= $i > 0 ? 'hidden' : '' ?>><?php if (!empty($storyExamples)): ?><small>Exemplo</small><?php endif; ?><?php $rating = !empty($storyExamples) ? 5 : max(0, min(5, (int) ($story['avaliacao'] ?? 0))); if ($rating > 0): ?><span class="members-story-stars" aria-label="<?= $rating ?> de 5 estrelas"><?= str_repeat('★', $rating) ?></span><?php endif; ?><p class="members-story-quote">“<?= htmlspecialchars($story['texto'], ENT_QUOTES, 'UTF-8') ?>”</p><div class="members-story-person"><?php if (!empty($story['foto'])): ?><img src="<?= htmlspecialchars($story['foto'], ENT_QUOTES, 'UTF-8') ?>" alt=""><?php else: ?><span class="members-story-photo" aria-hidden="true">◉</span><?php endif; ?><div><strong><?= htmlspecialchars($story['nome'], ENT_QUOTES, 'UTF-8') ?></strong><span><?= htmlspecialchars($story['profissao'] ?? '', ENT_QUOTES, 'UTF-8') ?></span></div></div></article><?php endforeach; ?><div class="members-story-controls"><button type="button" data-story-prev aria-label="Depoimento anterior">←</button><span data-story-position>1 / <?= count($storyCards) ?></span><button type="button" data-story-next aria-label="Próximo depoimento">→</button></div></div><?php endif; ?></div></section>
